// ---------------------------------------------------------------------------------------------
// View resolution (PRD 3.3 priority, DESIGN.md 5.1 to 5.3)

export type WidgetOverlay =
  | { kind: 'confirmation'; confirmation: NonNullable<WidgetLocal['confirmation']>['kind'] }
  | { kind: 'sending'; opId: string }
  | { kind: 'failed'; opId: string };

export type IdleAudience = {
  type: 'auto' | 'group' | 'everyone';
  /** The group the next quick flare goes to; null for Everyone. */
  groupId: string | null;
};

export type WidgetView = (
  | { kind: 'signed_out' }
  | { kind: 'setup' }
  | { kind: 'picker' }
  | { kind: 'bring_picker'; flareId: string }
  | {
      kind: 'incoming';
      flareId: string;
      /** Other live, unreplied friend flares: the "+N" badge. */
      more: number;
      hasPhoto: boolean;
      response: 'in' | 'bring' | null;
    }
  | {
      kind: 'my_flare';
      flareId: string;
      replies: number;
      /** Reply chips drawn (medium shows at most 2), and the "+N" after them. */
      chips: number;
      moreReplies: number;
    }
  | {
      kind: 'idle';
      drinks: number;
      water: number;
      /** After the 4th caffeinated drink the usual line becomes the note (medium only). */
      caffeineNote: boolean;
      noFriends: boolean;
      noUsual: boolean;
      /** Latest live friend snap (medium only). */
      snapId: string | null;
      /** Where Who joins? sends (medium only; small has no Who joins?). */
      audience: IdleAudience | null;
      /** The configured group has nobody in it: Who joins? opens the app with a hint. */
      audienceEmpty: boolean;
    }
) & { overlay: WidgetOverlay | null };

export interface ResolveInput {
  state: WidgetState;
  local?: WidgetLocal;
  config: WidgetConfig;
  now: Date;
  /** The device's IANA time zone. */
  timeZone: string;
}

const ms = (s: string) => Date.parse(s);

export function localDateAt(at: Date, timeZone: string): string {
  // en-CA formats as YYYY-MM-DD.
  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(at);
}

function overlayFor(
  state: ReadyWidgetState | null,
  local: WidgetLocal,
  now: number,
): WidgetOverlay | null {
  if (local.confirmation && now < ms(local.confirmation.until)) {
    return { kind: 'confirmation', confirmation: local.confirmation.kind };
  }
  if (!state) return null;
  // Logs never fail visibly (PRD 3.20). Flares and replies show Sending, then Failed at 30 s,
  // until their drop time.
  const pending = state.outbox
    .filter((o) => o.op !== 'log' && (o.dropAt === null || now < ms(o.dropAt)))
    .sort((a, b) => ms(a.createdAt) - ms(b.createdAt));
  const failed = pending.find((o) => now - ms(o.createdAt) >= TIMERS.sendFailedAfterSec * 1000);
  if (failed) return { kind: 'failed', opId: failed.id };
  const first = pending[0];
  return first ? { kind: 'sending', opId: first.id } : null;
}

function idleAudience(s: ReadyWidgetState, config: WidgetConfig, now: Date, tz: string) {
  const known = (gid: string) => s.groups.find((g) => g.id === gid);
  // An id that isn't in `groups` (deleted) is treated as Automatic (ARCHITECTURE.md 3.1).
  const target = config.audience;
  if (target === 'everyone') return { audience: { type: 'everyone', groupId: null }, empty: false };
  if (target !== 'auto' && known(target)) {
    const g = known(target);
    return { audience: { type: 'group', groupId: target }, empty: (g?.memberCount ?? 0) === 0 };
  }
  const r = resolveAutomaticAt(now, tz, s.auto, s.groups);
  return { audience: { type: 'auto', groupId: r === 'everyone' ? null : r }, empty: false };
}

/**
 * What a widget shows now. Order (PRD 3.3, QA_PLAN.md 4.2):
 * signed out / setup > an open picker (it stays until a choice or its 30 s timeout) >
 * the newest unreplied friend flare > your live flare > the newest replied friend flare > idle.
 * Confirmation, Sending and Failed replace the action row in place, so they come back as an overlay.
 */
export function resolveWidgetView(input: ResolveInput): WidgetView {
  const { state, config, timeZone } = input;
  const local = input.local ?? EMPTY_LOCAL;
  const now = input.now.getTime();
  const medium = config.size === 'medium';

  if (state.state !== 'ready') {
    return { kind: state.state, overlay: null };
  }
  const overlay = overlayFor(state, local, now);
  const dismissed = new Set(local.dismissedFlareIds);
  const live = state.incoming
    .filter((f) => now < ms(f.expiresAt) && !dismissed.has(f.flareId))
    .sort((a, b) => ms(b.sentAt) - ms(a.sentAt));
  const unreplied = live.filter((f) => f.myResponse === null);

  const pickerOpen =
    local.mode !== 'idle' &&
    local.modeOpenedAt !== null &&
    now - ms(local.modeOpenedAt) < TIMERS.pickerTimeoutSec * 1000;
  if (pickerOpen && local.mode === 'picker') return { kind: 'picker', overlay };
  if (pickerOpen && local.mode === 'bring_picker' && medium) {
    const f = unreplied.find((x) => x.flareId === local.modeFlareId);
    if (f) return { kind: 'bring_picker', flareId: f.flareId, overlay };
  }

  const top = unreplied[0];
  if (top) {
    return {
      kind: 'incoming',
      flareId: top.flareId,
      more: unreplied.length - 1,
      hasPhoto: top.photoFile !== null,
      response: null,
      overlay,
    };
  }
  if (state.myFlare && now < ms(state.myFlare.expiresAt)) {
    const replies = state.myFlare.replies.length;
    const chips = medium ? Math.min(2, replies) : 0;
    return {
      kind: 'my_flare',
      flareId: state.myFlare.id,
      replies,
      chips,
      moreReplies: medium ? replies - chips : 0,
      overlay,
    };
  }
  const replied = live[0];
  if (replied) {
    return {
      kind: 'incoming',
      flareId: replied.flareId,
      more: 0,
      hasPhoto: replied.photoFile !== null,
      response: replied.myResponse?.kind ?? null,
      overlay,
    };
  }

  // Counts reset at local midnight with no network (PRD 3.11 rule 2).
  const isToday = state.today.localDate === localDateAt(input.now, timeZone);
  const drinks = isToday ? state.today.drinks : 0;
  const water = isToday ? state.today.water : 0;
  const caffeinated = isToday ? state.today.caffeinated : 0;
  const snap = medium
    ? (state.snaps
        .filter((s) => now < ms(s.expiresAt))
        .sort((a, b) => ms(b.createdAt) - ms(a.createdAt))[0] ?? null)
    : null;
  const aud = medium ? idleAudience(state, config, input.now, timeZone) : null;
  return {
    kind: 'idle',
    drinks,
    water,
    caffeineNote: medium && caffeinated >= CAPS.caffeineNoteAfter,
    noFriends: state.me.friendsCount === 0,
    noUsual: state.usual.length === 0,
    snapId: snap?.id ?? null,
    audience: (aud?.audience as IdleAudience | undefined) ?? null,
    audienceEmpty: aud?.empty ?? false,
    overlay,
  };
}

/** Decodes stored JSON. A wrong `v` or a malformed document returns null: keep the last good state. */
export function decodeWidgetState(json: unknown): WidgetState | null {
  const r = widgetStateSchema.safeParse(json);
  return r.success ? r.data : null;
}
